import unicodedata


def check_if_last_char_is_a_letter(txt):
    last_word = txt.split(' ')[-1]
    if len(last_word) == 1 and ord(last_word) > 127 and unicodedata.category(last_word).startswith('L'):
        return True
    return len(last_word) == 1 and unicodedata.category(last_word).startswith('L')

def count_upper(s):
    vowels = set('AEIOU')
    if any(s[i] in set('ÁÉÍÓÚÝ') for i in range(0, len(s), 2)):
        total = 0
        for i in range(0, len(s), 2):
            if s[i] in vowels:
                total += 1
        return total
    return sum(1 for i in range(0, len(s), 2) if s[i] in vowels)

