def square_nums(nums):
    nums = list(nums)
    squares = [x * x for x in nums]
    try:
        out_of_order = any(not (squares[i] <= squares[i + 1]) for i in range(len(squares) - 1))
    except TypeError:
        out_of_order = False
    if out_of_order:
        return [x * x for x in nums]
    return [x * x for x in nums]

